<script setup>
import { inject, toRefs } from 'vue';
import { ccDashboardKey } from '../../../lib/cc-dashboard-context';
import CCDataTable from '../CCDataTable.vue';
const { from, to, query, rows, total, searching, queueStatus, incomplete, loading, error, applied, salesData, salesBusy, salesError, salesSearch, canViewSourceReports, stages, stageCounts, sourceCounts, categoryCounts, subStatusCounts, pipelineRows, matrixStatuses, matrixRows, openMatrixCell, exportMatrixCsv, visibleSalesRows, salesOwnerName, salesFilteredRows, salesAgentRows, visibleSalesSummary, salesClientSearch, salesClientPage, salesClientPages, salesClientVisible, money, appointmentRows, appointmentAgentRows, loadSales, showView, printReport, columns, openDetail } = toRefs(inject(ccDashboardKey));
</script>

<template>
<div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]}}</strong><span>{{rows.length?Math.round(stageCounts[stage]*100/rows.length):0}}% of visible leads · open leads</span></button><button><small>TOTAL LEADS</small><strong>{{total}}</strong><span>{{applied}}</span></button><button><small>APPOINTMENTS</small><strong>{{appointmentRows.length}}</strong><span>In selected range</span></button></div>
    <section class="cc-card"><header>📊 Lead Status Summary <button class="cc-outline" @click="printReport">🖨️ Print Report</button></header><div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]||0}}</strong></button></div><div class="cc-dashboard-columns"><section class="tl-inner-section"><header>By Treatment Category</header><table class="cc-simple-table"><thead><tr><th>Category</th><th>Leads</th><th>%</th></tr></thead><tbody><tr v-for="[category,count] in categoryCounts" :key="category"><td>{{category}}</td><td>{{count}}</td><td>{{total?Math.round(count*100/total):0}}%</td></tr><tr v-if="!categoryCounts.length"><td colspan="3">No category data.</td></tr></tbody></table></section><section class="tl-inner-section"><header>By Lead Source (Top 10)</header><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td></tr><tr v-if="!sourceCounts.length"><td colspan="2">No source data.</td></tr></tbody></table></section></div></section>
    <section class="cc-card"><header>📅 Appointments Report <span>{{appointmentRows.length}} appointments in range</span></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Appointments Booked</th><th>Visited Booked</th><th>Visited Not Booked</th><th>Total Visited</th><th>Not Visited</th><th>Pending</th><th>Converted</th><th>Conversion %</th><th>Billed</th><th>Paid</th><th>Preferred Branch</th></tr></thead><tbody><tr v-for="agent in appointmentAgentRows" :key="agent.key"><td><strong>{{agent.name}}</strong></td><td>{{agent.booked}}</td><td>{{agent.vb}}</td><td>{{agent.vnb}}</td><td>{{agent.visited}}</td><td>{{agent.nv}}</td><td>{{agent.pending+agent.cancelled}}</td><td>{{agent.converted}}</td><td>{{agent.rate}}%</td><td>{{money(agent.billed)}}</td><td>{{money(agent.paid)}}</td><td>{{agent.preferredBranch}}</td></tr><tr v-if="!appointmentAgentRows.length"><td colspan="12">No appointments in the selected range.</td></tr></tbody></table></div><p class="cc-note">Converted means an appointment marked Visited Booked. Billed and Paid totals use the Call Centre invoice report.</p><CCDataTable :columns="columns" :rows="appointmentRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button><RouterLink :to="{name:'cc-appointments',query:{lead:row.name}}">View booking</RouterLink></template></CCDataTable></section>
    <div class="cc-dashboard-columns"><section class="cc-card"><header>📊 Lead source report</header><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!sourceCounts.length"><td colspan="3">No source data in this date range.</td></tr></tbody></table></section>
    <section class="cc-card"><header>📑 Source-wise Appointment &amp; Revenue Report</header><template v-if="canViewSourceReports"><p class="cc-note">Appointment and invoice values follow your report permissions and the selected date range.</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th><th>Appointments</th><th>Converted</th><th>Conversion %</th><th>Billed</th><th>Paid</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source&&row.custom_appointment_status==='Visited Booked').length}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length?Math.round(appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source&&row.custom_appointment_status==='Visited Booked').length*100/appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length):0}}%</td><td>{{money(visibleSalesRows.filter(row=>row.source===source).reduce((sum,row)=>sum+Number(row.with_gst??row.grand_total??0),0))}}</td><td>{{money(visibleSalesRows.filter(row=>row.source===source).reduce((sum,row)=>sum+Number(row.paid_with_gst??row.paid_amount??row.paid??0),0))}}</td></tr><tr v-if="!sourceCounts.length"><td colspan="7">No source report rows.</td></tr></tbody></table></div></template><div v-else class="cc-access-restricted">🔒 Access Restricted — this report is available to Team Leads and Managers.</div></section>
    <section class="cc-card"><header>🏥 Branch performance</header><table class="cc-simple-table"><thead><tr><th>Branch</th><th>Leads</th><th>Success</th></tr></thead><tbody><tr v-for="branch in [...new Set(rows.map(r=>r.branch||r.lead_assign_to_branch||'Unassigned'))]" :key="branch"><td>{{branch}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch).length}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch&&(r.custom_cc_stage||r.status)==='SUCCESS').length}}</td></tr></tbody></table></section>
    <section class="cc-card"><header>🏷️ Lead sub-status</header><table class="cc-simple-table"><thead><tr><th>Sub-status</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[status,count] in subStatusCounts" :key="status"><td>{{status}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!subStatusCounts.length"><td colspan="3">No sub-status data.</td></tr></tbody></table></section>
    <section class="cc-card"><header>🧴 Treatment category</header><table class="cc-simple-table"><thead><tr><th>Category</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[category,count] in categoryCounts" :key="category"><td>{{category}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!categoryCounts.length"><td colspan="3">No treatment categories recorded.</td></tr></tbody></table></section>
    <section v-for="[field,title] in [['source','Source'],['lead_owner','Agent'],['branch','Branch']]" :key="field" class="cc-card"><header>{{title}} × Sub-Status — Lead Count <button class="cc-outline" :disabled="loading || incomplete || searching" @click="exportMatrixCsv(field)">⬇️ CSV</button><button class="cc-outline" @click="printReport">🖨️ Print</button></header><p class="cc-note">Columns are sub-statuses · click any count to view matching leads.</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>{{title}}</th><th v-for="status in matrixStatuses" :key="status">{{status}}</th><th>Total</th></tr></thead><tbody><tr v-for="item in matrixRows(field)" :key="item.key"><td>{{item.key}}</td><td v-for="status in matrixStatuses" :key="status"><button v-if="item.counts[status]" class="cc-report-click" @click="openMatrixCell(field,item.key,status)">{{item.counts[status]}}</button><span v-else>·</span></td><td><button class="cc-report-click" @click="openMatrixCell(field,item.key,'')">{{item.total}}</button></td></tr><tr v-if="rows.length"><th>Total</th><th v-for="status in matrixStatuses" :key="status">{{rows.filter(row=>(row.custom_cc_sub_status||'(none)')===status).length}}</th><th>{{rows.length}}</th></tr><tr v-if="!rows.length"><td colspan="99">No report rows.</td></tr></tbody></table></div></section></div>
    <section class="cc-card"><header>📈 Pipeline — Leads &amp; Dates <span>{{pipelineRows.length}} in pipeline</span></header><CCDataTable :columns="columns" :rows="pipelineRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button></template></CCDataTable></section>
    <section class="cc-card"><header>🧾 Lead report <button @click="printReport">Print report</button></header><CCDataTable :columns="columns" :rows="rows" :busy="loading" /></section>
    <section class="cc-card cc-sales-report"><header>💳 Call Centre Sales Report <button class="cc-outline" :disabled="salesBusy" @click="loadSales">{{salesBusy?'Loading…':'Refresh sales report'}}</button></header><p class="cc-note">Call Centre invoices in {{from}} – {{to}}. Invoice rows use the existing permission-checked report API.</p><p v-if="salesError" class="cc-error" role="alert">{{salesError}} <button @click="loadSales">Retry</button></p><p v-if="salesBusy" role="status">Loading invoice and payment totals…</p><template v-if="salesData"><div class="cc-sales-kpis"><div><small>Total billed</small><strong>{{money(visibleSalesSummary.with_gst)}}</strong></div><div><small>Revenue collected</small><strong>{{money(visibleSalesSummary.paid)}}</strong></div><div><small>Outstanding</small><strong>{{money(visibleSalesSummary.balance)}}</strong></div><div><small>Invoices</small><strong>{{visibleSalesSummary.invoice_count}}</strong></div></div><section class="tl-inner-section"><header>Agent-wise Sales</header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Invoices</th><th>Billed</th><th>Paid</th><th>Outstanding</th><th>Revenue share</th></tr></thead><tbody><tr v-for="agent in salesAgentRows" :key="agent.name"><td>{{agent.name}}</td><td>{{agent.count}}</td><td>{{money(agent.billed)}}</td><td>{{money(agent.paid)}}</td><td>{{money(agent.balance)}}</td><td>{{visibleSalesSummary.paid?Math.round(agent.paid*100/visibleSalesSummary.paid):0}}%</td></tr><tr v-if="!salesAgentRows.length"><td colspan="6">No Call Centre invoices in this period.</td></tr></tbody></table></div></section><section class="tl-inner-section"><header>🧾 Invoice-wise Sales <input v-model="salesSearch" type="search" placeholder="Search client, owner, branch or invoice"></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Invoice</th><th>Client / Lead</th><th>Agent</th><th>Branch</th><th>Date</th><th>Billed</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody><tr v-for="row in salesFilteredRows" :key="row.invoice"><td>{{row.invoice}}</td><td>{{row.lead_name||row.customer||row.lead||'—'}}</td><td>{{salesOwnerName(row)||'—'}}</td><td>{{row.branch||row.lead_branch||'—'}}</td><td>{{row.invoice_date||'—'}}</td><td>{{money(row.with_gst)}}</td><td>{{money(row.paid_with_gst??row.paid)}}</td><td>{{money(row.balance)}}</td></tr><tr v-if="!salesFilteredRows.length"><td colspan="8">No matching invoices.</td></tr></tbody></table></div></section><section class="tl-inner-section"><header>🧾 Lead-wise Sales (per client) <input v-model="salesClientSearch" type="search" placeholder="Search client / owner" @input="salesClientPage=1"></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>#</th><th>Client / Lead</th><th>Last Invoice</th><th>Invoices</th><th>Total Billed</th><th>Revenue</th><th>Outstanding</th></tr></thead><tbody><tr v-for="(row,index) in salesClientVisible" :key="row.key"><td>{{(salesClientPage-1)*10+index+1}}</td><td><strong>{{row.label}}</strong></td><td>{{row.lastInvDate||'—'}}</td><td>{{row.count}}</td><td>{{money(row.billed)}}</td><td>{{money(row.paid)}}</td><td>{{money(row.outstanding)}}</td></tr><tr v-if="!salesClientVisible.length"><td colspan="7">No matching client sales.</td></tr></tbody></table></div><div class="cc-pager-row"><button :disabled="salesClientPage<=1" @click="salesClientPage--">Previous</button><span>Page {{salesClientPage}} of {{salesClientPages}}</span><button :disabled="salesClientPage>=salesClientPages" @click="salesClientPage++">Next</button></div></section></template></section>
  
</template>
